head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL35300";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35300.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goFlashURL
 * @description go Flash URL 처리
 * @param {*} div div
 * @returns {void}
 * @hidden N
 */
scwin.goFlashURL = function (div) {
    let goUrl = '/';
    if (div === '11') {
        goUrl = '/submission/searchDisclosureDocument.do?method=searchSubmittedDisclosureDocument';
    } else {
        if (div === '12') {
            goUrl = '/submission/searchDisclosureForm.do?method=findEditClassList';
        } else {
            if (div === '13') {
                goUrl = '/submission/searchDisclosureDocument.do?method=searchSubmittedDisclosureDocument';
            } else {
                if (div === '14') {
                    goUrl = '/submission/searchDisclosureForm.do?method=findEditClassList';
                } else {
                    if (div === '15') {
                        goUrl = '/submission/searchDisclosureDocument.do?method=searchChangeDocument';
                    } else {
                        if (div === '16') {
                            goUrl = '/submission/searchDisclosureDocument.do?method=searchAttachDocument';
                        } else {
                            if (div === '17') {
                                goUrl = '/submission/searchDisclosureDocument.do?method=searchChangeDocument';
                            } else {
                                if (div === '18') {
                                    goUrl = '/submission/searchDisclosureDocument.do?method=searchWritingDocument';
                                } else {
                                    if (div === '19') {
                                        goUrl = '/submission/searchDisclosureDocument.do?method=searchEnglishDocument';
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc(null, (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(goUrl));
};
